/* ===== module: formulas/prs.js ===== */
    /** Personal-record detection: pure comparisons of current sets vs prior sets.
        Plain-English rules: 'e1rm' = the current session's best estimated 1RM
        beats the prior best by more than PR_E1RM_TOLERANCE (0.5 lb — keeps
        rounding noise from flagging PRs); 'heaviest' = the current session's
        top set is heavier than any prior set; bodyweight rep PRs compare
        unweighted sets only (a weighted set's reps are a different movement
        class); timed PRs (#282) compare longest hold at the SAME load.
        Callers own the definition of "prior" (all history vs other workouts) —
        see priorSetsForPR in lib/utilities.js for the shared prior definition.
        Depends on: estimate1RM (e1rm.js) — read at CALL time.
        Worked example: current=[{w:225,r:5}], prior best e1RM 240 →
        detectExercisePRs returns 'e1rm' iff estimate1RM(225×5) > 240.5. */

    /* → assets/js/formulas/volume.js: SECONDARY_MUSCLE_WEIGHT — moved here in the v1.878 restructure (no behavior change). */
    /* PR detection core: compares current sets against prior sets and reports
       which PR kind (if any) the current work achieves — 'e1rm' for a new
       estimated-1RM best, 'heaviest' for a new heaviest set. The tolerance
       keeps tiny rounding noise from flagging e1RM PRs. Callers own the
       definition of "prior" (all history vs. other workouts). Shared by the
       live-workout PR label and the Stats recent-PRs list. */
    const PR_E1RM_TOLERANCE=0.5;

    function detectExercisePRs(currentSets,priorSets){
      const current=currentSets||[],prior=priorSets||[];
      if(!current.length||!prior.length)return '';
      const best=Math.max(...current.map(estimate1RM)),priorBest=Math.max(...prior.map(estimate1RM));
      if(best>priorBest+PR_E1RM_TOLERANCE)return 'e1rm';
      const weight=Math.max(...current.map(set=>Number(set.w)||0)),priorWeight=Math.max(...prior.map(set=>Number(set.w)||0));
      if(weight>priorWeight)return 'heaviest';
      return '';
    }

    /* FORK v1.991.67 (R7, fix-list item 11): the ONE session-PR detector
       every PR surface reads — the live toast (workout-editor.js
       livePRKinds), the finished log's "PRs hit" (workout-history.js
       workoutPRs) and Stats Recent PRs (dashboard-stats.js
       recentPRRows). Before this, each surface ran its own comparison:
       the toast fired per set with a one-kind-per-exercise cap, while
       the session surfaces emitted at most ONE weighted kind via
       detectExercisePRs' e1rm-first priority — so a session that set
       both records (a heaviest single plus a back-off set whose e1RM
       beat the prior best) toasted "heaviest set PR" and then listed
       only the e1RM PR, and a distance PR toasted live had no session
       surface at all. The kinds are INDEPENDENT improvement events
       here (the bodyweight kind already co-fired with the weighted
       kinds in workoutPRs): a session can earn any subset.
       Contract (callers own these, identically on every surface):
       - both pools hold LOGGED sets only (complete === false excluded;
         a missing flag is a legacy logged set);
       - side gating, when the session is side-tracked, is applied by
         the caller to BOTH pools before calling (weaker-side pools);
       - "prior" is chronologically prior sessions only.
       Settled semantics, unchanged: a PR is an improvement over a
       prior best — every kind requires a prior pool of its own class,
       so a first-ever (baseline) performance earns no kind on any
       lift, weighted, bodyweight, timed or distance alike.
       cls is the item's tracking class: 'time' → timed only,
       'distance' → distance only, anything else → the rep kinds
       ('e1rm', 'heaviest', 'bw'), returned in that order. */
    function sessionPRKinds(currentSets,priorSets,cls){
      const current=currentSets||[],prior=priorSets||[];
      if(cls==='time')return detectTimedPRs(current,prior)?['timed']:[];
      if(cls==='distance')return (typeof detectDistancePRs==='function'&&detectDistancePRs(current,prior))?['distance']:[];
      const kinds=[];
      const curW=current.filter(set=>Number(set.w)>0&&Number(set.r)>0);
      const priW=prior.filter(set=>Number(set.w)>0&&Number(set.r)>0);
      if(curW.length&&priW.length){
        if(Math.max(...curW.map(estimate1RM))>Math.max(...priW.map(estimate1RM))+PR_E1RM_TOLERANCE)kinds.push('e1rm');
        if(Math.max(...curW.map(set=>Number(set.w)||0))>Math.max(...priW.map(set=>Number(set.w)||0)))kinds.push('heaviest');
      }
      if(detectBodyweightPRs(current,prior))kinds.push('bw');
      return kinds;
    }

    /* #703 (user 2026-10-23): rep-count PRs — beating the prior best
       weight AT an exact rep count is its own improvement event
       ("20-rep PR · 190 lb"), independent of the e1RM/heaviest
       kinds: a high-rep best usually moves neither. Rules, matching
       the settled PR semantics: a rep count enters only when the
       prior pool holds at least one weighted set at that count (a
       first performance at a count is a baseline, not a PR), and
       the current best at the count must strictly beat the prior
       best. Exception: the set that sets a new all-time heaviest
       does not ALSO mint its rep-count event — the heaviest-set PR
       alone announces that set (no double event). The exclusion is
       that one set: another set at the same count beating the
       prior best still earns the count's event at its own weight.
       Returns [{reps, weight}] in canonical units, reps ascending;
       callers format the display value. */
    function repCountPRs(currentSets,priorSets){
      const cur=(currentSets||[]).filter(s=>Number(s.w)>0&&Number(s.r)>0);
      const pri=(priorSets||[]).filter(s=>Number(s.w)>0&&Number(s.r)>0);
      if(!cur.length||!pri.length)return [];
      const priorBestAt=new Map();
      for(const s of pri){const r=Number(s.r),w=Number(s.w);if(!priorBestAt.has(r)||w>priorBestAt.get(r))priorBestAt.set(r,w);}
      const work=new Map();
      for(const s of cur){const r=Number(s.r);if(!work.has(r))work.set(r,[]);work.get(r).push(Number(s.w));}
      const priorMax=Math.max(...pri.map(s=>Number(s.w))),curMax=Math.max(...cur.map(s=>Number(s.w)));
      if(curMax>priorMax){
        const topSet=cur.find(s=>Number(s.w)===curMax);
        const arr=work.get(Number(topSet.r));
        arr.splice(arr.indexOf(curMax),1);
        if(!arr.length)work.delete(Number(topSet.r));
      }
      const out=[];
      for(const [r,ws] of work){
        if(!priorBestAt.has(r))continue;
        const best=Math.max(...ws);
        if(best>priorBestAt.get(r))out.push({reps:r,weight:best});
      }
      out.sort((a,b)=>a.reps-b.reps);
      return out;
    }

    /* #282: timed-PR detection — longest hold at a given load. A hold beats
       the prior best at the SAME load (unweighted = load 0); a load with no
       prior hold is new territory, so any hold there is a PR — mirroring how
       'heaviest' treats a new top weight. Callers own the "prior" definition,
       same contract as detectExercisePRs. */
    function detectTimedPRs(currentSets,priorSets){
      const current=(currentSets||[]).filter(s=>Number(s.seconds)>0),prior=(priorSets||[]).filter(s=>Number(s.seconds)>0);
      if(!current.length||!prior.length)return false;
      const load=s=>Number(s.w)||0;
      const bestAt=target=>{const pool=prior.filter(s=>load(s)===target);return pool.length?Math.max(...pool.map(s=>Number(s.seconds))):-Infinity;};
      return current.some(s=>Number(s.seconds)>bestAt(load(s)));
    }

    /* #372: bodyweight rep-PR detection — best unweighted rep set. estimate1RM
       is 0 for load-free sets, so bodyweight bests never registered as PRs
       anywhere. A rep count beats the prior best among UNWEIGHTED sets only
       (a weighted set's reps are a different movement class); no prior
       unweighted work means no PR, matching the weighted path's first-session
       rule. Callers own the "prior" definition, same contract as
       detectExercisePRs.
       FORK v1.992.31 (FR-218): comparability rule, stated in full —
       the 'bw' kind compares UNWEIGHTED rep sets (no load: w blank, 0
       or missing, r > 0) against UNWEIGHTED prior rep sets of the
       same exercise, whole-exercise pools (no per-side split —
       FR-222 removed side gating from every PR kind). Added-load
       sets (a weighted vest, a held plate) never enter either side
       of this comparison: they compete only for 'e1rm'/'heaviest'
       against weighted priors, so the two bases can never mint or
       block each other's PRs. Timed and distance work never reach
       this function (sessionPRKinds routes by tracking class first).
       Warm-up sets follow the PR path's settled treatment — they
       COUNT in both pools, for this kind exactly as for the weighted
       kinds (no warm-up filter at the detector or any caller, in
       either app; the D7 counting census, FORK v1.992.21 P2-7) —
       unlike the progression BASIS, which excludes warm-ups and is
       not a PR surface. Strictly-greater only: a tie is no PR, and
       an empty unweighted prior pool is a baseline, not a PR. */
    function detectBodyweightPRs(currentSets,priorSets){
      const unweighted=sets=>(sets||[]).filter(s=>!(Number(s.w)>0)&&Number(s.r)>0);
      const current=unweighted(currentSets),prior=unweighted(priorSets);
      if(!current.length||!prior.length)return false;
      return Math.max(...current.map(s=>Number(s.r)))>Math.max(...prior.map(s=>Number(s.r)));
    }
